// Scans twelve 112-byte submarine records and processes those with either low activation flag set.
// Forms target-minus-position shifted right 12 in a shared data block, normalizes it and derives a
// perpendicular using fixed-point cross products against up to three fallback reference vectors.
// Computes horizontal magnitude through the bit-count helper and lookup table, derives pitch and
// yaw with Submarine_Atan2Fixed and clears roll; reads the installed rotation matrix pointer but
// does not use it.
// FUNCTION: FF7 0x0078cbd0
void __cdecl Submarine_ComputeRecordPitchYaw(void)
{
    struct {
        int leadingBits;
        int scaleShift;
        int squaredZ;
        int horizontal;
        VECTOR cross;
        int offsetZ;
        SubmarineRelativeRecord *relRecord;
        VECTOR fallback;
        int offsetY;
        VECTOR direction;
        int offsetX;
        SubmarineContactRecord *modelData;
        PsxMatrix *rotMatrix;
    } frame; /* Stack frame layout: see FRAME UNION in lib/codegen.h. */

    frame.rotMatrix = GetInstalledRotMatrixPtr();
    frame.relRecord = (SubmarineRelativeRecord *)Gfx_GetPsxScratchpadPtr(0);
    frame.modelData = (SubmarineContactRecord *)&g_SubmarineModelVertexData;
    do {
        if ((frame.modelData->flags & 3) == 0) { /* empty first arm: lib/codegen.h */
        } else {
            frame.relRecord->offset.x = (frame.modelData->timedKey->waypointX - frame.modelData->posX) >> 0xC;
            frame.relRecord->offset.y = (frame.modelData->timedKey->waypointY - frame.modelData->posY) >> 0xC;
            frame.relRecord->offset.z = (frame.modelData->timedKey->waypointZ - frame.modelData->posZ) >> 0xC;
            Submarine_NormalizeVectorInPlace(&frame.relRecord->offset);
            frame.direction.vx = frame.relRecord->offset.x;
            frame.direction.vy = frame.relRecord->offset.y;
            frame.direction.vz = frame.relRecord->offset.z;
            frame.fallback.vx = g_SubmarineUpVectorX;
            frame.fallback.vy = g_SubmarineUpVectorY;
            frame.fallback.vz = g_SubmarineUpVectorZ;
            CrossProductFixed12(&frame.direction, &frame.fallback, &frame.cross);
            frame.relRecord->side.x = frame.cross.vx;
            frame.relRecord->side.y = frame.cross.vy;
            frame.relRecord->side.z = frame.cross.vz;
            if (Submarine_NormalizeVectorInPlace(&frame.relRecord->side) == 0) {
                frame.fallback.vx = g_SubmarineState.copyVector;
                frame.fallback.vy = g_SubmarineState.copyVectorY;
                frame.fallback.vz = g_SubmarineState.copyVectorZ;
                CrossProductFixed12(&frame.direction, &frame.fallback, &frame.cross);
                frame.relRecord->side.x = frame.cross.vx;
                frame.relRecord->side.y = frame.cross.vy;
                frame.relRecord->side.z = frame.cross.vz;
                if (Submarine_NormalizeVectorInPlace(&frame.relRecord->side) == 0) {
                    frame.fallback.vx = g_SubmarineState.seedVector;
                    frame.fallback.vy = g_SubmarineState.seedVectorY;
                    frame.fallback.vz = g_SubmarineState.seedVectorZ;
                    CrossProductFixed12(&frame.direction, &frame.fallback, &frame.cross);
                    frame.relRecord->side.x = frame.cross.vx;
                    frame.relRecord->side.y = frame.cross.vy;
                    frame.relRecord->side.z = frame.cross.vz;
                    Submarine_NormalizeVectorInPlace(&frame.relRecord->side);
                }
            }
            frame.offsetX = frame.relRecord->offset.x;
            frame.offsetY = 0;
            frame.offsetZ = frame.relRecord->offset.z;
            frame.cross.vx = frame.offsetX * frame.offsetX;
            frame.cross.vz = frame.offsetZ * frame.offsetZ;
            frame.horizontal = frame.cross.vx;
            frame.squaredZ = frame.cross.vz;
            frame.horizontal += frame.squaredZ;
            frame.leadingBits = Bit_CountLeadingSignBits(frame.horizontal);
            frame.leadingBits = frame.leadingBits >> 1 << 1;
            frame.scaleShift = (0x1F - frame.leadingBits) / 2;
            if (frame.leadingBits == 0x20) {
                frame.horizontal = 0;
            }
            if (frame.leadingBits < 0x18) {
                frame.horizontal >>= 0x18 - frame.leadingBits;
            } else {
                frame.horizontal <<= frame.leadingBits - 0x18;
            }
            frame.horizontal = g_SubmarineModelIndicesA[frame.horizontal - 64] << frame.scaleShift >> 0xC;
            frame.modelData->angleC = -Submarine_Atan2Fixed(frame.relRecord->offset.y, frame.horizontal);
            frame.modelData->angleD = -Submarine_Atan2Fixed(frame.relRecord->side.z, frame.relRecord->side.x);
            frame.modelData->angleE = 0;
        }

        frame.modelData++;
    } while ((unsigned int)frame.modelData < (unsigned int)&g_SubmarineLevel0Map);
}
/* Fixed-point 2-argument arc tangent calculating angle in 0..4095 range. */
// FUNCTION: FF7 0x0078ce96
int __cdecl Submarine_Atan2Fixed(int x, int y)
{
    // These names place the four locals at the original VC5 stack offsets.
    int result;
    int absY;
    int xabs;
    int swap;

    result = 0;
    if (x < 0) {
        xabs = -x;
    } else {
        xabs = x;
    }
    if (y < 0) {
        absY = -y;
    } else {
        absY = y;
    }
    if (absY == 0) {
        if (xabs == 0) {
            return 0;
        }
        result = 0x400;
        /* goto kept: the original jumps to a stub after the function end that jumps on; falling out of the if jumps directly */
        goto signs;
    } else {
        swap = 0;
        if (xabs >= absY) {
            swap = absY;
            absY = xabs;
            xabs = swap;
            swap = 1;
        }
        result = ArcTangentFixed(xabs, absY);
        if (swap == 1) {
            result = 0x400 - result;
        }
    }
signs:
    if (y < 0) {
        result = 0x800 - result;
    }
    if (x < 0) {
        result = -result;
    }
    return result;
}

// Computes squared vector magnitude, derives its even normalization exponent, indexes two fixed
// tables and scales all three input components in place by the selected reciprocal-like factor and
// shift. Returns that factor; the second table-derived local value is computed but unused.
// FUNCTION: FF7 0x0078cf5e
int __cdecl Submarine_NormalizeVectorInPlace(SubmarineVec3Int *vector)
{
    int ySquared;
    int dstZPow;
    int unusedSpace; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    int xSquared;
    int vx;
    int signFlags;
    int totalSq;
    int reciprocal;
    int expBits;
    int zComp;
    int vecY;

    vx = vector->x;
    vecY = vector->y;
    zComp = vector->z;
    xSquared = vx * vx;
    ySquared = vecY * vecY;
    dstZPow = zComp * zComp;
    totalSq = xSquared + ySquared + dstZPow;
    signFlags = Bit_CountLeadingSignBits(totalSq);
    signFlags = signFlags >> 1 << 1;
    expBits = ((0x1F - signFlags) / 2);
    if (signFlags == 0x20) {
        totalSq = 0;
    }
    if (signFlags < 0x18) {
        totalSq >>= 0x18 - signFlags;
    } else {
        totalSq <<= signFlags - 0x18;
    }
    reciprocal = g_SubmarineModelIndicesB[totalSq - 64];
    totalSq = g_SubmarineModelIndicesA[totalSq - 64];
    xSquared = vx * reciprocal;
    ySquared = vecY * reciprocal;
    dstZPow = zComp * reciprocal;
    totalSq = totalSq << expBits >> 0xC;
    vx = xSquared;
    vecY = ySquared;
    zComp = dstZPow;
    vector->x = vx >> expBits;
    vector->y = vecY >> expBits;
    vector->z = zComp >> expBits;
    return reciprocal;
}

// Updates twelve 0x70-byte submarine records. Active records turn pitch and heading toward their
// wrapped targets by signed steps of 4 and 8, recompute a fixed-point direction, move using
// current speed and approach target speed. Out-of-bounds movement clears motion bit 1 and sets bit
// 2, skipping all later processing for that record. Bit 0x20 records descend toward terrain, alter
// angles and position, then clear themselves and update counters. Computes waypoint distance,
// camera-relative distance, normalized direction and threshold flags through lookup tables;
// follows the next waypoint when close. Nonpositive health enters the terrain descent state.
// Otherwise services four timed effect slots, potentially initializes a free effect record among
// indices 16 through 31, maintains proximity-dependent state and timers, and decrements or rearms
// effect slots. The first free effect record terminates the search even when distance prevents
// initialization.
