// Looks for the LOCKED contact: drops it to none when the record is out of range (flag 0x10 clear),
// to LOST with frameCount 0x2D when flag 4 is clear, or returns when both are set and the lock
// holds. Then locks (frameCount 0x2D) the TRACKED in-range record with flag 4 and the smallest
// signed magnitude.
// FUNCTION: FF7 0x0078e2f8
void __cdecl Submarine_UpdateActiveFlagRecord(void)
{
    SubmarineContactRecord *rec;
    int minLimit;
    SubmarineContactRecord *bestPtr;

    rec = (SubmarineContactRecord *)&g_SubmarineModelVertexData;
    do {
        if ((rec->state & SUBMARINE_CONTACT_LOCKED) != 0) {
            if ((rec->flags & 0x10) == 0) {
                rec->state = 0;
                rec->frameCount = 0;
                break;
            }
            if ((rec->flags & 4) == 0) {
                rec->state = SUBMARINE_CONTACT_LOST;
                rec->frameCount = 0x2d;
                break;
            }
            return;
        }
        rec++;
    } while ((unsigned int)rec < (unsigned int)&g_SubmarineLevel0Map);

    minLimit = 0x7fffffff;
    bestPtr = 0;
    rec = (SubmarineContactRecord *)&g_SubmarineModelVertexData;
    do {
        if ((rec->flags & 4) != 0 &&
            (rec->flags & 0x10) != 0 &&
            (rec->state & SUBMARINE_CONTACT_TRACKED) != 0 &&
            minLimit > rec->magnitude) {
            minLimit = rec->magnitude;
            bestPtr = rec;
        }
        rec++;
    } while ((unsigned int)rec < (unsigned int)&g_SubmarineLevel0Map);
    if (bestPtr != 0) {
        bestPtr->state = SUBMARINE_CONTACT_LOCKED;
        bestPtr->frameCount = 0x2d;
    }
}

