// Builds the level's object records from the actor table of one level block; called by
// Submarine_SelectSubmarineDataBlocks. Clears the active and effect
// counts and the total slot weight, then converts the twelve 0x30-byte actor definitions into
// the twelve 0x70-byte records at g_SubmarineModelVertexData (the loop stops at the next object,
// g_SubmarineLevel0Map). Each record gets the position in grid units turned into 20.12 fixed
// point (shifted left by 18), the slot weight, two angles, the height offset, speed, timer and
// flags. When flag bit 0 is set the actor is active: its timedKey is linked to row routeIndex of
// the working route table and its modelDescriptor to entry modelIndex of
// g_SubmarineModelDescriptors, the active count goes up and its weight is added to the total. Unlike the route links
// Submarine_FillRouteRecordTable writes, neither index is clamped here.
// FUNCTION: FF7 0x0078e882
void __cdecl Submarine_CopyObjectRecordTable(SubmarineObjectRecord *objectRecords)
{
    SubmarineContactRecord *dst;
    int index;

    g_SubmarineEffectCount0 = 0;
    g_SubmarineEffectCount1 = 0;
    g_SubmarineActiveSlotCount = 0;
    g_SubmarineSlotTotalWeight = 0;
    index = 0;
    dst = (SubmarineContactRecord *)&g_SubmarineModelVertexData;
    do {
        dst->posX = objectRecords->posX << 6 << 0xC;
        dst->posY = objectRecords->posY << 6 << 0xC;
        dst->posZ = objectRecords->posZ << 6 << 0xC;
        dst->slotWeight = objectRecords->slotWeight;
        dst->angleA = objectRecords->angleA;
        dst->angleB = objectRecords->angleB;
        dst->heightOffset = objectRecords->heightOffset;
        dst->speed = objectRecords->speed;
        dst->timer = objectRecords->timer;
        dst->flags = objectRecords->flags;
        if ((objectRecords->flags & 1) != 0) {
            dst->timedKey = (SubmarineTimedEffectKey *)g_SubmarineWorkingLevelRouteTable[objectRecords->routeIndex];
            dst->modelDescriptor = &g_SubmarineModelDescriptors[objectRecords->modelIndex];
            g_SubmarineEffectCount0++;
            g_SubmarineSlotTotalWeight += objectRecords->slotWeight;
        }
        objectRecords++;
        index++;
        dst++;
    } while ((unsigned int)dst < (unsigned int)&g_SubmarineLevel0Map);
}

